+const { execFile, execFileSync } = require('node:child_process');
+const fs = require('node:fs');
+const os = require('node:os');
+const path = require('node:path');
+const { promisify } = require('node:util');
+const chai = require('chai');
+
+chai.should();
+
+const execFileAsync = promisify(execFile);
+
+describe('scripts/test-db/select_db_host.sh', function () {
+    let tempDir;
+    let binDir;
+    let realAwk;
+
+    beforeEach(function () {
+        tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'select-db-host-'));
+        binDir = path.join(tempDir, 'bin');
+        fs.mkdirSync(binDir);
+        realAwk = execFileSync('which', ['awk'], { encoding: 'utf8' }).trim();
+    });
+
+    afterEach(function () {
+        fs.rmSync(tempDir, { recursive: true, force: true });
+    });
+
+    function writeExecutable(name, contents) {
+        const filePath = path.join(binDir, name);
+        fs.writeFileSync(filePath, contents, { mode: 0o755 });
+    }
+
+    function env() {
+        return {
+            ...process.env,
+            PATH: `${binDir}${path.delimiter}${process.env.PATH}`,
+            REAL_AWK: realAwk,
+        };
+    }
+
+    it('selects the host with the lowest normalized load without using reserved awk names', async function () {
+        writeExecutable(
+            'awk',
+            `#!/bin/sh
+for arg in "$@"; do
+  case "$arg" in
+    load=*) echo "awk: fatal: cannot use gawk builtin \`load' as variable name" >&2; exit 2 ;;
+  esac
+done
+exec "$REAL_AWK" "$@"
+`,
+        );
+        writeExecutable(
+            'ssh',
+            `#!/bin/sh
+host=""
+command=""
+for arg in "$@"; do
+  case "$arg" in deploy@*) host="\${arg#deploy@}" ;; esac
+  command="$arg"
+done
+case "$command" in
+  *"/proc/loadavg"*)
+    case "$host" in
+      db-a) echo "4.00" ;;
+      db-b) echo "3.00" ;;
+      *) exit 1 ;;
+    esac
+    ;;
+  *"nproc"*)
+    case "$host" in
+      db-a) echo "2" ;;
+      db-b) echo "4" ;;
+      *) exit 1 ;;
+    esac
+    ;;
+  *) exit 1 ;;
+esac
+`,
+        );
+
+        const { stdout, stderr } = await execFileAsync(
+            './scripts/test-db/select_db_host.sh',
+            ['db-a db-b'],
+            { env: env() },
+        );
+
+        stdout.trim().should.equal('db-b');
+        stderr.should.contain('db-a: load=4.00 cpus=2 normalized=2.00');
+        stderr.should.contain('db-b: load=3.00 cpus=4 normalized=0.75');
+    });
+
+    it('falls back to the first host when all probes fail', async function () {
+        writeExecutable(
+            'awk',
+            `#!/bin/sh
+exec "$REAL_AWK" "$@"
+`,
+        );
+        writeExecutable(
+            'ssh',
+            `#!/bin/sh
+exit 1
+`,
+        );
+
+        const { stdout, stderr } = await execFileAsync(
+            './scripts/test-db/select_db_host.sh',
+            ['db-a db-b'],
+            { env: env() },
+        );
+
+        stdout.trim().should.equal('db-a');
+        stderr.should.contain('All host checks failed, falling back to db-a');
+    });
+});

